class Solution {
    public int maxCount(int m, int n, int[][] ops) {
        int minRows = m;
        int minCols = n;
        for (int[] op : ops) {
            minRows = Math.min(minRows, op[0]);
            minCols = Math.min(minCols, op[1]);
        }
        return minRows * minCols;
    }
}

class Solution {
    public int maxCount(int m, int n, int[][] ops) {
        int top = 0;
        int left = 0;
        int bottom = m;
        int right = n;
        for (int[] op : ops) {
            bottom = Math.min(bottom, op[0]);
            right = Math.min(right, op[1]);
        }
        return (bottom - top) * (right - left);
    }
}

class Solution {
    public int maxCount(int m, int n, int[][] ops) {
        if (ops.length == 0) {
            return m * n;
        }
        int[] rowLimits = new int[ops.length];
        int[] colLimits = new int[ops.length];
        for (int i = 0; i < ops.length; i++) {
            rowLimits[i] = ops[i][0];
            colLimits[i] = ops[i][1];
        }
        java.util.Arrays.sort(rowLimits);
        java.util.Arrays.sort(colLimits);
        return rowLimits[0] * colLimits[0];
    }
}
